#!/bin/sh
# the licence gate (docs/security/supply-chain.md section 7).
# ci.yml's licences job and local runs both call this script, so the steps
# that feed scripts/supply-chain/licences.py live in one place:
#   - go modules downloaded, so trivy reads their licences from the cache
#   - the collector distribution generated by ocb (dist/scf-otelcol), because
#     the collector image links modules that the root go.mod does not list
#   - the packages of the real console bundle
#   - trivy's package lists of the repository and of the collector module
#
#   scripts/supply-chain/licence-gate.sh <output dir>
#
# needs go, node with the workspace installed (pnpm install) and trivy
# 0.76.2 on PATH.
set -eu

if [ $# -ne 1 ]; then
	echo "usage: $0 <output dir>" >&2
	exit 2
fi
out="$1"
root="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$root"
mkdir -p "$out"

trivy --version | grep -q '^Version: 0\.76\.2$' || { echo "trivy is not 0.76.2" >&2; exit 1; }

# go mod download all writes a checksum for every module of the build list
# into go.sum, including test-only dependencies of dependencies that the
# committed go.sum leaves out. the scan needs them in the module cache, not
# in the repository, so both files are put back on exit and a local run
# leaves the tree as it found it
sums="$(mktemp -d)"
cp go.sum "$sums/root"
cp examples/otel-go-nethttp/go.sum "$sums/example"
restore() {
	cp "$sums/root" go.sum
	cp "$sums/example" examples/otel-go-nethttp/go.sum
	rm -rf "$sums"
}
trap restore EXIT
go mod download all
(cd examples/otel-go-nethttp && go mod download all)
# same ocb version and manifest as make collector-build; sources only. ocb
# creates dist/scf-otelcol but not its parent, and a fresh checkout has no
# dist/ (it is gitignored)
mkdir -p dist
go run go.opentelemetry.io/collector/cmd/builder@v0.165.0 \
	--config collector/builder-config.yaml --skip-compilation --skip-strict-versioning=false
(cd dist/scf-otelcol && go mod download all)

node apps/console/scripts/bundle-packages.mjs >"$out/console-bundle.txt"

trivy fs --quiet --scanners vuln --list-all-pkgs --format json --output "$out/pkgs.json" \
	--skip-dirs resources --skip-dirs dist .
trivy fs --quiet --scanners vuln --list-all-pkgs --format json --output "$out/otelcol.json" \
	dist/scf-otelcol

python3 -I scripts/supply-chain/licences.py "$out/pkgs.json" --otelcol "$out/otelcol.json" \
	--console-bundle "$out/console-bundle.txt" --report "$out/licences.json"
